export function getLang() {
  return localStorage.getItem('wllpr-lang') || 'en';
}

export function setLang(lang) {
  localStorage.setItem('wllpr-lang', lang);
  window.location.reload();
}

export function t(key) {
  return translations[getLang()][key];
}

export function initI18n() {
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    if (translations[getLang()][key]) {
      if (el.tagName === 'INPUT' && el.type === 'button') {
        el.value = translations[getLang()][key];
      } else {
        let hasElementChildren = false;
        for (let i = 0; i < el.childNodes.length; i++) {
          if (el.childNodes[i].nodeType === 1) {
            hasElementChildren = true;
            break;
          }
        }
        if (hasElementChildren) {
          for (let i = 0; i < el.childNodes.length; i++) {
            if (el.childNodes[i].nodeType === 3 && el.childNodes[i].textContent.trim().length > 0) {
              el.childNodes[i].textContent = " " + translations[getLang()][key] + " ";
              break;
            }
          }
        } else {
          el.textContent = translations[getLang()][key];
        }
      }
    }
  });

  const selectLang = document.getElementById('langSelect');
  if (selectLang) {
    const current = getLang();
    // Populate options
    selectLang.innerHTML = '';
    for (const [code, data] of Object.entries(translations)) {
      const option = document.createElement('option');
      option.value = code;
      option.textContent = data.name;
      if (code === current) {
        option.selected = true;
      }
      selectLang.appendChild(option);
    }
    
    selectLang.onchange = (e) => {
      setLang(e.target.value);
    };
  }
}
